const { useEffect, useState } = React;
const storageKey = 'lesson-demo:settings';
const defaultSettings = { theme: 'light', fontSize: 16 };

function Settings() {
  const [settings, setSettings] = useState(() => {
    const saved = localStorage.getItem(storageKey);
    return saved ? JSON.parse(saved) : defaultSettings;
  });

  useEffect(() => {
    localStorage.setItem(storageKey, JSON.stringify(settings));
    console.log('저장:', settings);
  }, [settings]);

  return (
    <section>
      <p>테마: {settings.theme} / 글자: {settings.fontSize}px</p>
      <button type="button" onClick={() => setSettings(current => ({ ...current, theme: current.theme === 'light' ? 'dark' : 'light' }))}>테마</button>
      <button type="button" onClick={() => setSettings(current => ({ ...current, fontSize: current.fontSize + 1 }))}>글자 키우기</button>
      <button type="button" onClick={() => setSettings(defaultSettings)}>기본값</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Settings />);

