    document.querySelector('#stored').textContent = saved.theme;
  }, [settings]);
  return <button type="button" onClick={() => setSettings({ theme: 'dark' })}>어둡게</button>;
}
ReactDOM.createRoot(document.querySelector('#root')).render(<Settings />);
